INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q28162861', 'Siege of Melite', 'The siege of Melite was the capture of the Byzantine city of Melite (modern Mdina, Malta) by an invading Aghlabid army in 870 AD. The siege was initially led by Halaf al-Hādim, a renowned engineer, but he was killed and replaced by Sawāda Ibn Muḥammad. The city withstood the siege for some weeks or months, but it ultimately fell to the invaders, and its inhabitants were massacred and the city was sacked.', 870, NULL, NULL, NULL, NULL, NULL, 'year', '870', 37, 'https://en.wikipedia.org/wiki/Siege_of_Melite_(870)'),
  ('Q28216518', 'Siege of Medina', 'The siege of Medina was an unsuccessful Byzantine attack on the Muslim city of Medina (modern Mdina), Malta in 1053 or 1054. The Muslim inhabitants of the city and their slaves managed to repel a superior Byzantine force, which retreated with heavy losses.', 1053, NULL, NULL, NULL, NULL, NULL, 'year', '1053', 34, 'https://en.wikipedia.org/wiki/Siege_of_Medina_(1053%E2%80%931054)'),
  ('Q56276752', 'Norman invasion of Malta', 'The Norman invasion of Malta was an attack on the island of Malta, then inhabited predominantly by Muslims, by forces of the Norman County of Sicily led by Roger I in 1091. The invaders besieged Medina (modern Mdina), the main settlement on the island, but the inhabitants managed to negotiate peace terms.', 1091, 7, NULL, NULL, NULL, NULL, 'month', 'July 1091', 39, 'https://en.wikipedia.org/wiki/Norman_invasion_of_Malta'),
  ('Q20706642', 'Siege of Malta', 'The siege of Malta, also known as the siege of Mdina, was a Hafsid invasion of the island of Malta, then part of the Kingdom of Sicily (itself part of the Crown of Aragon), in September and October 1429. After capturing Mazara on nearby Sicily, a Hafsid force landed on Malta, besieged the island''s main city of Mdina and skirmished with the defenders.', 1429, 9, NULL, NULL, NULL, NULL, 'month', 'September 1429', 39, 'https://en.wikipedia.org/wiki/Siege_of_Malta_(1429)'),
  ('Q58732', 'Siege of Malta', 'The Great Siege of Malta (Maltese: L-Assedju l-Kbir) occurred in 1565 when the Ottoman Empire attempted to conquer the island of Malta, then held by the Knights Hospitaller. The siege lasted nearly four months, from 18 May to 8 September 1565.', 1565, 5, 18, 1565, 9, 8, 'day', '18 May 1565 – 8 September 1565', 76, 'https://en.wikipedia.org/wiki/Great_Siege_of_Malta'),
  ('Q20204978', 'Rising of the Priests', 'The Rising of the Priests (Maltese: Ir-Rewwixta tal-Qassisin), also known as the September 1775 Rebellion, was an uprising against the Knights Hospitaller which broke out in Valletta, Hospitaller Malta in September 1775. It came about after an extended period of political and economic tension following the death of Grand Master Manuel Pinto da Fonseca in 1773.', 1775, 9, 8, NULL, NULL, NULL, 'day', '8 September 1775', 41, 'https://en.wikipedia.org/wiki/Rising_of_the_Priests'),
  ('Q207318', 'French Revolutionary Wars', 'The French Revolutionary Wars (French: Guerres de la Révolution française) were a series of sweeping military conflicts resulting from the French Revolution that lasted from 1792 until 1802. They pitted France against Great Britain, Austria, Prussia, Russia, and several other countries.', 1792, 4, 20, 1802, 3, 25, 'day', '20 April 1792 – 25 March 1802', 77, 'https://en.wikipedia.org/wiki/French_Revolutionary_Wars'),
  ('Q2493908', 'Siege of Malta', 'The siege of Malta, also known as the siege of Valletta or the French blockade (Maltese: L-Imblokk tal-Franċiżi), was a two-year siege and blockade of the French garrison in Valletta and the Three Cities, the largest settlements and main port on the Mediterranean island of Malta, between 1798 and 1800. Malta had been captured by a French expeditionary force during the Mediterranean campaign of 1798, and garrisoned with 3,000 soldiers under the command of Claude-Henri Belgrand de Vaubois.', 1798, 9, 2, 1800, 9, 4, 'day', '2 September 1798 – 4 September 1800', 51, 'https://en.wikipedia.org/wiki/Siege_of_Malta_(1798%E2%80%931800)'),
  ('Q682452', 'Siege of Malta', 'The Siege of Malta (or Battle of Malta) in World War II was a military campaign in the Mediterranean theatre. From June 1940 to November 1942, the fight for the control of the strategically important island of the British Crown Colony of Malta pitted the air and naval forces of the Kingdom of Italy and Nazi Germany against the Royal Air Force (RAF) and the Royal Navy.', 1940, 6, 11, 1942, 11, 20, 'day', '11 June 1940 – 20 November 1942', 67, 'https://en.wikipedia.org/wiki/Siege_of_Malta_(World_War_II)'),
  ('Q6744844', 'Maltese divorce referendum, 2011', 'A referendum on divorce was held in Malta on 28 May 2011. Voters were asked whether they approved of a new law to introduce allowing divorces, as at that time, Malta was one of only three countries in the world (along with the Philippines and the Vatican City) in which divorce was not permitted.', 2011, 5, 28, NULL, NULL, NULL, 'day', '28 May 2011', 34, 'https://en.wikipedia.org/wiki/2011_Maltese_divorce_referendum'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q19820103', 'Maltese spring hunting referendum, 2015', 'A referendum on spring hunting was held in Malta on 11 April 2015. Voters voted narrowly in favour of retaining the spring hunt, with 50.4% voting for the existing law to remain in place.', 2015, 4, 11, NULL, NULL, NULL, 'day', '11 April 2015', 37, 'https://en.wikipedia.org/wiki/2015_Maltese_spring_hunting_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
